/**
 * @description Centralized test data factory for creating test records across all test classes.
 * This factory follows Salesforce best practices by providing reusable methods for test data creation,
 * reducing code duplication and improving test maintainability.
 *
 * @group Testing Utilities
 * @date 2025-10-23
 */
@IsTest
public class TestDataFactory {
    // Date constants for predictable testing
    public static final Date TEST_START_DATE = Date.newInstance(2025, 1, 1);
    public static final Date TEST_END_DATE = Date.newInstance(2025, 12, 31);
    public static final Date TEST_DUE_DATE = Date.newInstance(2025, 6, 30);

    // Batch size constants
    public static final Integer SMALL_BATCH_SIZE = 5;
    public static final Integer MEDIUM_BATCH_SIZE = 10;
    public static final Integer BULK_BATCH_SIZE = 200;
    public static final Integer LARGE_BULK_SIZE = 250;

    // Default values
    public static final String DEFAULT_PROJECT_STATUS = 'Active';
    public static final String DEFAULT_WORK_ITEM_STATUS = 'Not Started';
    public static final String DEFAULT_RESOURCE_TYPE = 'Internal User';
    public static final String DEFAULT_ACCESS_LEVEL = 'Read/Write';
    public static final Decimal DEFAULT_ESTIMATED_HOURS = 40.0;

    /**
     * @description Get test start date
     * @return Date - Test start date constant
     */
    public static Date getStartDate() {
        return TEST_START_DATE;
    }

    /**
     * @description Get test end date
     * @return Date - Test end date constant
     */
    public static Date getEndDate() {
        return TEST_END_DATE;
    }

    /**
     * @description Get test due date
     * @return Date - Test due date constant
     */
    public static Date getDueDate() {
        return TEST_DUE_DATE;
    }

    /**
     * @description Calculate date relative to start date
     * @param days Number of days to add to start date
     * @return Date - Calculated date
     */
    public static Date getDateDaysFromStart(Integer days) {
        return TEST_START_DATE.addDays(days);
    }

    /**
     * @description Creates a project template with default values
     * @return Project_Template__c - Inserted project template
     */
    public static Project_Template__c createProjectTemplate() {
        return createProjectTemplate('Test Project Template');
    }

    /**
     * @description Creates a project template with specified name
     * @param name Template name
     * @return Project_Template__c - Inserted project template
     */
    public static Project_Template__c createProjectTemplate(String name) {
        Project_Template__c template = new Project_Template__c(Name = name, Description__c = 'Test template for projects');
        insert as user template;
        return template;
    }

    /**
     * @description Creates a work item template with default values
     * @return Work_Item_Template__c - Inserted work item template
     */
    public static Work_Item_Template__c createWorkItemTemplate() {
        return createWorkItemTemplate('Test Work Item Template', true);
    }

    /**
     * @description Creates a work item template with specified name
     * @param name Template name
     * @param active Whether template is active
     * @return Work_Item_Template__c - Inserted work item template
     */
    public static Work_Item_Template__c createWorkItemTemplate(String name, Boolean active) {
        Work_Item_Template__c template = new Work_Item_Template__c(Name = name, Description__c = 'Test template for work items', Active__c = active);
        insert as user template;
        return template;
    }

